__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"EFFECTIVE_DATE",{enumerable:!0,get:function(){return t}}),Object.defineProperty(e,"ARTICLES",{enumerable:!0,get:function(){return l}});const t='2026\ub144 11\uc6d4 7\uc77c',l=[{title:'1. \uc218\uc9d1\ud558\ub294 \uac1c\uc778\uc815\ubcf4',lines:['\ud68c\uc6d0\uac00\uc785\xb7\ub85c\uadf8\uc778: \uc774\uba54\uc77c \uc8fc\uc18c, \ube44\ubc00\ubc88\ud638(\ubcf5\uc6d0\ud560 \uc218 \uc5c6\uac8c \uc554\ud638\ud654\ud574 \uc800\uc7a5), \ub124\uc774\ubc84 \ub85c\uadf8\uc778 \uace0\uc720 \uc2dd\ubcc4\uac12(\uc774\uba54\uc77c\uc740 \ubc1b\uc9c0 \uc54a\uc74c), \uce74\uce74\uc624 \ub85c\uadf8\uc778 \ud68c\uc6d0\ubc88\ud638\xb7\ub2c9\ub124\uc784\xb7\ud504\ub85c\ud544 \uc0ac\uc9c4\uacfc \uc774\uba54\uc77c(\uc774\uc6a9\uc790\uac00 \ub3d9\uc758\ud55c \uacbd\uc6b0), \uc560\ud50c \ub85c\uadf8\uc778 \uc2dd\ubcc4\uac12\uacfc \uc774\uba54\uc77c(\uc560\ud50c\uc774 \uc81c\uacf5\ud558\ub294 \uacbd\uc6b0).','\uc11c\ube44\uc2a4 \uc774\uc6a9: \ucc1c\ud55c \ud14c\ub9c8, \ud50c\ub808\uc774 \uae30\ub85d(\ub0a0\uc9dc\xb7\uc131\uacf5 \uc5ec\ubd80\xb7\ub0a8\uae34 \uc2dc\uac04\xb7\ud78c\ud2b8\xb7\uc778\uc6d0\xb7\ubcc4\uc810\xb7\uba54\ubaa8 \ub4f1), \ub9ac\ubdf0, \uc608\uc57d \uc77c\uc815\uacfc \uba54\ubaa8, \uc228\uae34 \ud14c\ub9c8, \uc571 \uc124\uc815, \uc608\uc57d \uc624\ud508 \uc54c\ub9bc\uc744 \ucf20 \ud14c\ub9c8.','\ub2c9\ub124\uc784: \ub85c\uadf8\uc778\ud55c \uc774\uc6a9\uc790\uac00 \uc815\ud55c \ub2c9\ub124\uc784.','\ud504\ub85c\ud544 \uc0ac\uc9c4: \ub85c\uadf8\uc778\ud55c \uc774\uc6a9\uc790\uac00 \uc0ac\uc9c4 \ubcf4\uad00\ud568\uc5d0\uc11c \uace8\ub77c \uc62c\ub9b0 \uc0ac\uc9c4(\uc815\uc0ac\uac01\ud615\uc73c\ub85c \uc798\ub77c \uc904\uc5ec \uc800\uc7a5).','\uc608\uc57d \ucd08\ub300: \ucd08\ub300 \ub9c1\ud06c\ub85c \ucd94\uac00\ud55c \uc608\uc57d\uc774 \uc5b4\ub290 \ucd08\ub300\uc5d0\uc11c \uc654\ub294\uc9c0.','\uc54c\ub9bc: \ud734\ub300\ud3f0 \ud478\uc2dc \ud1a0\ud070 \ub610\ub294 \ube0c\ub77c\uc6b0\uc800 \ud478\uc2dc \uad6c\ub3c5 \uc815\ubcf4, \uae30\uae30 \uc885\ub958(\uc548\ub4dc\ub85c\uc774\ub4dc\xb7iOS\xb7\uc6f9).','\ud50c\ub808\uc774 \uc885\ub8cc \uc54c\ub9bc: \uc608\uc57d\ud55c \ud14c\ub9c8, \ub0a0\uc9dc\xb7\uc2dc\uac04\xb7\uc778\uc6d0. \uc608\uc57d \uba54\ubaa8\ub294 \uc885\ub8cc \uc54c\ub9bc \ubc1c\uc1a1\uc744 \uc704\ud574 \uc804\uc1a1\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.','\ubb38\uc758: \ubb38\uc758 \ub0b4\uc6a9\uacfc \ub2f5\ubcc0, \ub85c\uadf8\uc778\ud558\uc9c0 \uc54a\uc558\ub2e4\uba74 \uc774\uc6a9\uc790 \uae30\uae30\uc5d0 \uc800\uc7a5\ub418\ub294 \ubb38\uc758 \ubc88\ud638.','\uc790\ub3d9 \uc218\uc9d1: \uad11\uace0 \uc81c\uacf5\uc744 \uc704\ud574 \uc571\uc5d0\uc11c\ub294 Google AdMob \uc774 \uad11\uace0 \uc2dd\ubcc4\uc790 \ub4f1 \uae30\uae30 \uc815\ubcf4\ub97c, \uc6f9\uc0ac\uc774\ud2b8\uc5d0\uc11c\ub294 Google AdSense \uac00 \ucfe0\ud0a4\ub85c \ubc29\ubb38 \uc815\ubcf4\ub97c \uc218\uc9d1\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc6f9\uc0ac\uc774\ud2b8 \uc774\uc6a9 \ud1b5\uacc4\ub97c \uc704\ud574 Google \uc560\ub110\ub9ac\ud2f1\uc2a4\uac00 \ucfe0\ud0a4\ub85c \ubc29\ubb38\ud55c \ud654\uba74\xb7\uc774\uc6a9 \uc2dc\uac04\xb7\ube0c\ub77c\uc6b0\uc800\xb7\ub300\ub7b5\uc801\uc778 \uc9c0\uc5ed \ub4f1 \ubc29\ubb38 \uc815\ubcf4\ub97c \uc218\uc9d1\ud569\ub2c8\ub2e4. \ubc29\ub610\ub294 \uc774\uc6a9 \ud1b5\uacc4\ub97c \uc704\ud574 \uc571\xb7\uc6f9\uc0ac\uc774\ud2b8\uc5d0\uc11c \uae30\uae30\ub9c8\ub2e4 \ub9cc\ub4e0 \ubb34\uc791\uc704 \ubc88\ud638, \uc5f0 \ud654\uba74, \ub4e4\uc5b4\uc628 \uacf3(\ubc14\uae65 \ud398\uc774\uc9c0 \uc8fc\uc18c\xb7\uac80\uc0c9\uc5b4), \uae30\uae30\xb7\uc6b4\uc601\uccb4\uc81c\xb7\ube0c\ub77c\uc6b0\uc800 \uc885\ub958, \uc571 \ubc84\uc804\uacfc \ucc1c\xb7\uc54c\ub9bc \ucf1c\uae30 \uac19\uc740 \uc774\uc6a9 \uae30\ub85d\uc744 \uc800\uc7a5\ud558\uba70 \uc774\ub984\xb7IP \uc8fc\uc18c\ub294 \uc800\uc7a5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc774\uc6a9 \uc911 \uc624\ub958\uac00 \ub098\uba74 \uc624\ub958 \ub0b4\uc6a9, \uc624\ub958 \uc9c1\uc804\uc5d0 \uc5f0 \ud654\uba74\uacfc \ub204\ub978 \uae30\ub2a5 \uc774\ub984, \uae30\uae30\xb7\uc6b4\uc601\uccb4\uc81c\xb7\ube0c\ub77c\uc6b0\uc800 \uc885\ub958, \uc571 \ubc84\uc804, \ub85c\uadf8\uc778\ud588\ub2e4\uba74 \ub0b4\ubd80 \uacc4\uc815 \ubc88\ud638\ub97c \ud568\uaed8 \uc800\uc7a5\ud558\uba70 \uc785\ub825\ud55c \uae00\xb7\uac80\uc0c9\uc5b4\ub294 \uc800\uc7a5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.','\uc774\ubca4\ud2b8 \uc801\ub9bd\uae08 \uc9c0\uae09 \uc2e0\uccad: \uc774\ub984, \uc740\ud589\uba85, \uacc4\uc88c\ubc88\ud638(\uc9c0\uae09 \uc2e0\uccad\ud55c \uacbd\uc6b0\uc5d0\ub9cc).','\uc704\uce58: \uac00\uae4c\uc6b4 \uc21c \uc815\ub82c\uc744 \uace0\ub978 \uacbd\uc6b0\uc5d0\ub9cc \uae30\uae30\uc5d0\uc11c \ud604\uc7ac \uc704\uce58\ub97c \uc0ac\uc6a9\ud558\uba70, \uc11c\ubc84\ub85c \ubcf4\ub0b4\uac70\ub098 \uc800\uc7a5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.','\ub85c\uadf8\uc778\ud558\uc9c0 \uc54a\uc73c\uba74 \ucc1c\xb7\uae30\ub85d\xb7\uc124\uc815\uc740 \uc774\uc6a9\uc790 \uae30\uae30\uc5d0\ub9cc \uc800\uc7a5\ub418\uace0 \uc11c\ubc84\ub85c \ubcf4\ub0b4\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc54c\ub9bc\uc744 \ud5c8\uc6a9\ud55c \uacbd\uc6b0 \ubc1c\uc1a1\uc744 \uc704\ud55c \uae30\uae30 \uad6c\ub3c5\uacfc \uc624\ud508 \uc54c\ub9bc \ud14c\ub9c8\xb7\ud50c\ub808\uc774 \uc885\ub8cc \uc54c\ub9bc\uc5d0 \ud544\uc694\ud55c \uc608\uc57d \uc815\ubcf4\ub294 \uc11c\ubc84\uc5d0 \uc800\uc7a5\ud569\ub2c8\ub2e4.']},{title:'2. \uc774\uc6a9 \ubaa9\uc801',lines:['\ud68c\uc6d0 \uc2dd\ubcc4\uacfc \ub85c\uadf8\uc778, \ucc1c\xb7\uae30\ub85d\xb7\uc124\uc815\uc744 \uacc4\uc815\uc5d0 \uc800\uc7a5\ud574 \uc5ec\ub7ec \uae30\uae30\uc5d0\uc11c \uc774\uc5b4 \uc4f0\uae30.','\uc54c\ub9bc\uc744 \ucf20 \ud14c\ub9c8\uc758 \uc608\uc57d \uc624\ud508 5\ubd84\xb71\ubd84 \uc804 \uc54c\ub9bc \ubc1c\uc1a1, \uc774\uc6a9 \ub0a0\uc9dc\ub97c \uace0\ub978 \uc54c\ub9bc\uc740 12\uc2dc\uac04 \uc804 \ubbf8\ub9ac \uc54c\ub9bc \ud3ec\ud568.','\uc608\uc57d\ud55c \ud50c\ub808\uc774 \uc885\ub8cc 15\ubd84 \ud6c4 \uae30\ub85d \uc54c\ub9bc \ubc1c\uc1a1.','\ub9ac\ubdf0 \uac8c\uc2dc\uc640 \uc2e0\uace0 \ucc98\ub9ac, \ubb38\uc758 \ub2f5\ubcc0.','\ub85c\uadf8\uc778\ud55c \uc774\uc6a9\uc790\uc758 \ud50c\ub808\uc774 \uae30\ub85d \uc911 \ubcc4\uc810\xb7\uc7a5\uce58 \ube44\uc911\xb7\uccb4\uac10 \uacf5\ud3ec\xb7\ub9ac\ubdf0\ud3c9\uc740 \uae30\ubcf8\uc73c\ub85c \ub9ac\ubdf0\ub85c\ub3c4 \uacf5\uac1c\ub418\uba70, \uae30\ub85d \ud654\uba74\uc5d0\uc11c \uadf8 \uae30\ub85d\ub9cc \ub044\uac70\ub098 My \uc124\uc815\uc5d0\uc11c \ub04c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uba54\ubaa8\ub294 \uacf5\uac1c\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.','\ub2c9\ub124\uc784\uc740 \uc774\uc6a9\uc790\uac00 \uacf5\uac1c\ud55c \ub9ac\ubdf0\uc758 \uc791\uc131\uc790 \uc774\ub984\uc73c\ub85c \ub204\uad6c\uc5d0\uac8c\ub098 \ubcf4\uc774\uace0, \ubcf4\ub0b4\ub294 \uc608\uc57d \ucd08\ub300 \ubb38\uad6c\uc640 \uac19\uc740 \ucd08\ub300\ub85c \ud568\uaed8 \uac00\ub294 \uce5c\uad6c\uc758 \ub0b4 \uc608\uc57d \ud654\uba74\uc5d0 \ubcf4\uc785\ub2c8\ub2e4. \uc608\uc57d \uba54\ubaa8\uc640 \uc774\uba54\uc77c \ub4f1 \uacc4\uc815 \uc815\ubcf4\ub294 \ubcf4\uc774\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.','\ucd08\ub300 \ub9c1\ud06c\ub85c \uce5c\uad6c\ub97c \ub9fa\uc73c\uba74 \uce5c\uad6c\uc5d0\uac8c \ub2c9\ub124\uc784\uacfc \ub0b4\uac00 \ud574\ubcf8 \ud14c\ub9c8 \ubaa9\ub85d(\uae30\ub85d\uc744 \ub0a8\uae30\uac70\ub098 \ud50c\ub808\uc774\ud568\uc744 \uccb4\ud06c\ud55c \ud14c\ub9c8)\uc774 \ubcf4\uc785\ub2c8\ub2e4. \ubcc4\uc810\xb7\uba54\ubaa8 \ub4f1 \uae30\ub85d \ub0b4\uc6a9\uc740 \ubcf4\uc774\uc9c0 \uc54a\uc73c\uba70, \uce5c\uad6c \ud654\uba74\uc5d0\uc11c \uacf5\uac1c\ub97c \ub044\uac70\ub098 \uce5c\uad6c\ub97c \ub04a\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.','\ud504\ub85c\ud544 \uc0ac\uc9c4\uc740 \ub2c9\ub124\uc784\uacfc \ud568\uaed8 \uacf5\uac1c\ud55c \ub9ac\ubdf0\uc758 \uc791\uc131\uc790\uc640 \ubcf4\ub0b4\ub294 \uce5c\uad6c \ucd08\ub300 \ud654\uba74\uc5d0\uc11c\ub294 \ub204\uad6c\uc5d0\uac8c\ub098, \uce5c\uad6c \ubaa9\ub85d\uc5d0\uc11c\ub294 \uce5c\uad6c\uc5d0\uac8c \ubcf4\uc774\uba70, My \ud654\uba74\uc5d0\uc11c \uc5b8\uc81c\ub4e0\uc9c0 \ubc14\uafb8\uac70\ub098 \uc9c0\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.','\uc774\ubca4\ud2b8 \uc801\ub9bd\uae08 \uc9c0\uae09\uacfc \uc608\uae08\uc8fc \ud655\uc778, \uac19\uc740 \uacc4\uc88c\ub85c \uc5ec\ub7ec \uacc4\uc815\uc774 \uc2e0\uccad\ud558\ub294 \ub4f1 \ubd80\uc815 \ucc38\uc5ec \ud655\uc778.','\uc624\ub958 \uc6d0\uc778 \ud30c\uc545\uacfc \uc218\uc815.','\uad11\uace0 \ud45c\uc2dc\uc640 \uc11c\ube44\uc2a4 \uac1c\uc120.']},{title:'3. \ubcf4\uc720 \uae30\uac04\uacfc \ud30c\uae30',lines:['\ud68c\uc6d0 \ud0c8\ud1f4\ub97c \uc2e0\uccad\ud558\uba74 3\uc77c \ub4a4 \uacc4\uc815\uacfc \uacc4\uc815\uc5d0 \uc800\uc7a5\ub41c \ucc1c\xb7\uae30\ub85d\xb7\uc608\uc57d\xb7\ube44\uacf5\uac1c \ub9ac\ubdf0\xb7\uc124\uc815\xb7\ud504\ub85c\ud544 \uc0ac\uc9c4\uc744 \uc0ad\uc81c\ud569\ub2c8\ub2e4. 3\uc77c \uc548\uc5d0 \ub2e4\uc2dc \ub85c\uadf8\uc778\ud558\uba74 \ud0c8\ud1f4\ub97c \ucca0\ud68c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.','\ub2e4\ub978 \uc774\uc6a9\uc790\uc640 \ud568\uaed8 \uc4f0\ub294 \uacf5\uac1c \ub9ac\ubdf0\xb7\ub2e8\uccb4\ud1a1 \uba54\uc2dc\uc9c0\xb7\uac8c\uc2dc\ud310 \uae00\uc740 \ud0c8\ud1f4 \ub4a4\uc5d0\ub3c4 \uacc4\uc815\uacfc\uc758 \uc5f0\uacb0\uc744 \ub04a\uace0 \uc791\uc131\uc790\ub97c "\ud0c8\ud1f4\ud55c \ud68c\uc6d0"\uc73c\ub85c \ubc14\uafd4 \ub0a8\uae41\ub2c8\ub2e4. \uc9c0\uc6b0\uae30\ub97c \uc6d0\ud558\uba74 \ud0c8\ud1f4 \uc804\uc5d0 \uc9c1\uc811 \uc9c0\uc6b0\uac70\ub098 \ubb38\uc758\ud558\uae30\ub85c \uc694\uccad\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.','\ud504\ub85c\ud544 \uc0ac\uc9c4\uc740 \ubc14\uafb8\uac70\ub098 \uc9c0\uc6b0\uba74 \uc774\uc804 \uc0ac\uc9c4\uc744 \ubc14\ub85c \uc0ad\uc81c\ud569\ub2c8\ub2e4.','\uc774\uc6a9 \ud1b5\uacc4 \uae30\ub85d\uc740 400\uc77c\uc774 \uc9c0\ub098\uba74 \uc0ad\uc81c\ud569\ub2c8\ub2e4.','\uc624\ub958 \uae30\ub85d\uc740 90\uc77c\uc774 \uc9c0\ub098\uba74 \uc0ad\uc81c\ud558\uace0, \ud0c8\ud1f4\ud558\uba74 \uacc4\uc815\uacfc\uc758 \uc5f0\uacb0\uc744 \ub04a\uc2b5\ub2c8\ub2e4.','\ud478\uc2dc \ud1a0\ud070\uc740 \uc54c\ub9bc\uc744 \ubaa8\ub450 \ub044\uac70\ub098 \uc571 \uc0ad\uc81c\xb7\uc54c\ub9bc \ud574\uc81c\ub85c \ubc1c\uc1a1\uc774 \uc2e4\ud328\ud558\uba74 \uc0ad\uc81c\ud569\ub2c8\ub2e4.','\ud50c\ub808\uc774 \uc885\ub8cc \uc54c\ub9bc \uc815\ubcf4\ub294 \uc608\uc57d \uc0ad\uc81c\xb7\uae30\ub85d \uc644\ub8cc \uc2dc \ub3d9\uae30\ud654\ud574 \uc9c0\uc6b0\uba70, \ubc1c\uc1a1 \uc608\uc815 \uc2dc\uac01\ubd80\ud130 \ucd5c\ub300 7\uc77c\uac04 \ubcf4\uad00\ud569\ub2c8\ub2e4.','\ubb38\uc758\ub294 \ub2f5\ubcc0\uacfc \ucc98\ub9ac\ub97c \ub9c8\uce60 \ub54c\uae4c\uc9c0 \ubcf4\uad00\ud558\uace0 \uc774\ud6c4 \uc9c0\uccb4 \uc5c6\uc774 \uc0ad\uc81c\ud569\ub2c8\ub2e4.','\uc774\ubca4\ud2b8 \uc9c0\uae09 \uc2e0\uccad\uc758 \uacc4\uc88c\ubc88\ud638\ub294 \uc785\uae08\uc744 \ub9c8\uce58\uba74 \uc989\uc2dc \uc0ad\uc81c\ud558\uace0, \uc9c0\uae09 \ub0b4\uc5ed(\uacc4\uc815\xb7\uc774\ub984\xb7\uc740\ud589\xb7\uae08\uc561\xb7\ub0a0\uc9dc)\uc740 \ubb38\uc758 \ub300\uc751\uc744 \uc704\ud574 \uc9c0\uae09\uc77c\ubd80\ud130 1\ub144\uac04 \ubcf4\uad00\ud55c \ub4a4 \uc0ad\uc81c\ud569\ub2c8\ub2e4.','\uad00\uacc4 \ubc95\ub839\uc774 \ubcf4\uad00\uc744 \uc694\uad6c\ud558\ub294 \uacbd\uc6b0 \uadf8 \uae30\uac04 \ub3d9\uc548\ub9cc \ubd84\ub9ac\ud574 \ubcf4\uad00\ud569\ub2c8\ub2e4.']},{title:'4. \uc81c3\uc790 \uc81c\uacf5',lines:['\uc774\uc6a9\uc790\uc758 \ub3d9\uc758\ub098 \ubc95\ub839\uc5d0 \uadfc\uac70\uac00 \uc788\ub294 \uacbd\uc6b0\ub97c \uc81c\uc678\ud558\uace0 \uac1c\uc778\uc815\ubcf4\ub97c \uc81c3\uc790\uc5d0\uac8c \uc81c\uacf5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.']},{title:'5. \ucc98\ub9ac \uc704\ud0c1\uacfc \uad6d\uc678 \uc774\uc804',lines:['Supabase Inc.(\ubbf8\uad6d, \ub370\uc774\ud130\ub294 \ub300\ud55c\ubbfc\uad6d \uc11c\uc6b8 \ub9ac\uc804 \uc11c\ubc84\uc5d0 \uc800\uc7a5): \ud68c\uc6d0 \uc778\uc99d\uacfc \uc571 \ub370\uc774\ud130 \uc800\uc7a5.','650 Industries, Inc.(Expo, \ubbf8\uad6d): \uc571 \ud478\uc2dc \ubc1c\uc1a1, \uc6f9\uc0ac\uc774\ud2b8 \ud638\uc2a4\ud305, \uc571 \uc5c5\ub370\uc774\ud2b8 \ubc30\ud3ec.','Google LLC(\ubbf8\uad6d): Firebase Cloud Messaging \uc744 \ud1b5\ud55c \uc548\ub4dc\ub85c\uc774\ub4dc\xb7\ud06c\ub86c \uc54c\ub9bc \uc804\ub2ec, AdMob\xb7AdSense \uad11\uace0, Google \uc560\ub110\ub9ac\ud2f1\uc2a4 \uc6f9\uc0ac\uc774\ud2b8 \uc774\uc6a9 \ud1b5\uacc4.','Apple Inc.(\ubbf8\uad6d): \uc544\uc774\ud3f0\xb7\uc0ac\ud30c\ub9ac \uc54c\ub9bc \uc804\ub2ec, \uc560\ud50c \ub85c\uadf8\uc778.','\ub124\uc774\ubc84 \uc8fc\uc2dd\ud68c\uc0ac(\ub300\ud55c\ubbfc\uad6d): \ub124\uc774\ubc84 \ub85c\uadf8\uc778.','\uc8fc\uc2dd\ud68c\uc0ac \uce74\uce74\uc624(\ub300\ud55c\ubbfc\uad6d): \uce74\uce74\uc624 \ub85c\uadf8\uc778.','\uad6d\uc678 \uc774\uc804\uc740 \uc11c\ube44\uc2a4 \uc774\uc6a9 \uc2dc\uc810\uc5d0 \uc815\ubcf4\ud1b5\uc2e0\ub9dd\uc744 \ud1b5\ud574 \uc774\ub8e8\uc5b4\uc9c0\uba70, \uc704 \uc5c5\uccb4\uc758 \uc11c\ube44\uc2a4 \uc774\uc6a9 \uae30\uac04 \ub3d9\uc548 \ubcf4\uad00\ub429\ub2c8\ub2e4. \uad6d\uc678 \uc774\uc804\uc744 \uc6d0\ud558\uc9c0 \uc54a\uc73c\uba74 \ud68c\uc6d0 \ud0c8\ud1f4\ub85c \uac70\ubd80\ud560 \uc218 \uc788\uc73c\ub098 \ud574\ub2f9 \uae30\ub2a5\uc744 \uc4f8 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.']},{title:'6. \uc774\uc6a9\uc790\uc758 \uad8c\ub9ac',lines:['\uc774\uc6a9\uc790\ub294 \uc5b8\uc81c\ub4e0\uc9c0 \uc571\uc5d0\uc11c \uc790\uc2e0\uc758 \uae30\ub85d\xb7\ub9ac\ubdf0\xb7\uc124\uc815\uc744 \ud655\uc778\xb7\uc218\uc815\xb7\uc0ad\uc81c\ud560 \uc218 \uc788\uace0, My \ud654\uba74\uc758 \ud68c\uc6d0 \ud0c8\ud1f4\ub85c \uacc4\uc815\uacfc \ub370\uc774\ud130\ub97c \uc0ad\uc81c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.','\uc5f4\ub78c\xb7\uc815\uc815\xb7\uc0ad\uc81c\xb7\ucc98\ub9ac \uc815\uc9c0\ub97c \uc6d0\ud558\uba74 My \ud654\uba74\uc758 \ubb38\uc758\ud558\uae30\ub85c \uc694\uccad\ud560 \uc218 \uc788\uc73c\uba70 \uc9c0\uccb4 \uc5c6\uc774 \ucc98\ub9ac\ud569\ub2c8\ub2e4.','\ud734\ub300\ud3f0 \ub610\ub294 \ube0c\ub77c\uc6b0\uc800 \uc124\uc815\uc5d0\uc11c \uc54c\ub9bc\uacfc \uc704\uce58 \uad8c\ud55c\uc744 \uc5b8\uc81c\ub4e0\uc9c0 \ub04c \uc218 \uc788\uc2b5\ub2c8\ub2e4.','\ube0c\ub77c\uc6b0\uc800 \ucfe0\ud0a4 \uc124\uc815\uc774\ub098 Google \uad11\uace0 \uc124\uc815(adssettings.google.com)\uc5d0\uc11c \ub9de\ucda4 \uad11\uace0\ub97c \ub04c \uc218 \uc788\uace0, \ube0c\ub77c\uc6b0\uc800 \ucfe0\ud0a4\ub97c \ucc28\ub2e8\ud558\uac70\ub098 Google \uc560\ub110\ub9ac\ud2f1\uc2a4 \ucc28\ub2e8 \ubd80\uac00\uae30\ub2a5(tools.google.com/dlpage/gaoptout)\uc73c\ub85c \uc774\uc6a9 \ud1b5\uacc4 \uc218\uc9d1\uc744 \uac70\ubd80\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.']},{title:'7. \ub9cc 14\uc138 \ubbf8\ub9cc',lines:['\ub9cc 14\uc138 \ubbf8\ub9cc \uc544\ub3d9\uc740 \ud68c\uc6d0\uac00\uc785\uc744 \ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.']},{title:'8. \uc548\uc804\uc131 \ud655\ubcf4 \uc870\uce58',lines:['\ube44\ubc00\ubc88\ud638 \uc554\ud638\ud654 \uc800\uc7a5, \uc804\uc1a1 \uad6c\uac04 \uc554\ud638\ud654(HTTPS), \ub370\uc774\ud130 \uc811\uadfc \uad8c\ud55c \uc81c\ud55c(\uacc4\uc815\ubcc4 \uc811\uadfc \uc815\ucc45)\uc744 \uc801\uc6a9\ud569\ub2c8\ub2e4.']},{title:'9. \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\ucc45\uc784\uc790\uc640 \ubb38\uc758',lines:['\uac1c\uc778\uc815\ubcf4 \uad00\ub828 \ubb38\uc758\xb7\ubd88\ub9cc\xb7\ud53c\ud574 \uad6c\uc81c\ub294 My \ud654\uba74\uc758 \ubb38\uc758\ud558\uae30\ub85c \uc811\uc218\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.']},{title:'10. \ubcc0\uacbd',lines:['\uc774 \ubc29\uce68\uc774 \ubc14\ub00c\uba74 \uc571\uacfc \uc774 \ud398\uc774\uc9c0\uc5d0 \uc2dc\ud589\uc77c\uacfc \ud568\uaed8 \uc54c\ub9bd\ub2c8\ub2e4.']}]},1033,[]);